 const [rows,setRows]=useState<RecordRow[]>([]),[journeyStep,setJourneyStep]=useState(0),[answer,setAnswer]=useState(''),[quizCorrect,setQuizCorrect]=useState(false),[matchIndex,setMatchIndex]=useState(0),[feedback,setFeedback]=useState('');
