 const upcomingDates=Array.from({length:7},(_,i)=>{const d=new Date(wallTime+(i+1)*86400000);return new Intl.DateTimeFormat('en-CA',{timeZone:city.zone,year:'numeric',month:'2-digit',day:'2-digit'}).format(d);});
 // Geolocation is requested only by the nearest-place button; no coordinates are persisted or sent.
 function askLocation(){setLocationStatus(t('جارٍ طلب إذن الموقع…','Requesting location permission…'));if(!navigator.geolocation){setLocationStatus(t('الموقع غير متاح. ابحث بالمدينة.','Location is unavailable. Search by city.'));return;}navigator.geolocation.getCurrentPosition(p=>{const near=[...cities].sort((a,b)=>(a.lat-p.coords.latitude)**2+(a.lng-p.coords.longitude)**2-((b.lat-p.coords.latitude)**2+(b.lng-p.coords.longitude)**2))[0];setCitySearch(near[prefs.lang]);setLocationStatus(t('أقرب مدينة في الدليل التجريبي: '+near.ar+'. لم يُحفظ موقعك.','Nearest city in the sample directory: '+near.en+'. Your location was not saved.'));},()=>setLocationStatus(t('يمكنك المتابعة بالبحث باسم المدينة.','You can continue by searching for your city.')),{enableHighAccuracy:false,maximumAge:0,timeout:10000});}
