 const titleMap:Record<View,string>={now:t('لحظتك، الآن.','Your moment. Right now.'),explore:t('اتبع فضولك.','Follow your curiosity.'),journeys:t('فهمٌ يبقى معك.','Understanding that stays.'),passport:t('جواز لحظاتك.','Your moment passport.'),settings:t('على طريقتك.','Make it yours.'),discover:t('ما الذي لفت انتباهك؟','What caught your attention?'),chat:t('سؤال يفتح نافذة.','A question opens a window.'),detail:branch==='time'?(ar?prayerNames[moment as keyof typeof prayerNames]?.ar:(prayerNames[moment as keyof typeof prayerNames]?.en+', the '+prayerMeanings[moment as keyof typeof prayerMeanings]+' prayer')):momentName(moment),journey:txt(journey),experiences:t('من الفهم إلى اللقاء.','From understanding to meeting.'),booking:txt(selectedExperience),ticket:t('تذكرتك التجريبية','Your demo ticket'),privacy:t('خصوصيتك أولًا.','Your privacy comes first.'),about:t('عن لَحْظَة','About LAHZA'),impact:t('أثر السؤال','Question impact')};
