 {journeyStep===5&&<><div className="finish-stamp"><Stamp size={52}/><span>LAHZA</span></div><h2>{review?t('اكتملت معاينة الرحلة.','Journey preview complete.'):t('صار لك فهمٌ جديد.','A new understanding is yours.')}</h2><p>{review?t('هذه معاينة لمسودة. لا تمنح ختم تعلّم، ولا تغيّر حالة الاعتماد.','This is a draft preview. It awards no learning stamp and changes no review status.'):t('احتفظ بهذه الرحلة في جواز لحظاتك.','Keep this journey in your moment passport.')}</p><button className="primary" onClick={()=>{if(!review&&journeyReady){earn('journey-call-to-prayer','journey',journey.claimIds);save(PROGRESS,5);}go('passport');}}>{review?t('شاهد الجواز','View passport'):t('اختم جوازي','Stamp my passport')}</button></>}
