 {view==='passport'&&<><div className="passport-summary"><span><b>{stamps.filter(s=>s.type!=='visit-demo').length}</b> {t('لحظات فهم','moments understood')}</span><span className="badge"><ShieldCheck size={14}/>{t('على جهازك فقط','Only on this device')}</span></div><section className="passport-book" key={page}><div className="passport-top"><Compass size={25}/><span>LAHZA PASSPORT</span><span>{page+1} / 2</span></div><h2>{page===0?t('كل ختم، نافذة جديدة.','Every stamp, a new window.'):t('رحلات وتجارب.','Journeys and encounters.')}</h2><div className="stamp-grid">{(page===0?['adhan','wudu','iqamah','congregational-prayer']:['khutbah','journey-call-to-prayer','visit-demo']).map((id,i)=>{const stampId=id.startsWith('journey')||id==='visit-demo'?id:'moment-'+id,won=stamps.find(s=>s.id===stampId);return <button className={'passport-stamp '+(won?'earned':'locked')+' stamp-'+i} key={id} onClick={()=>{if(id==='visit-demo')go('experiences');else if(id.startsWith('journey'))go('journeys');else openMoment(id);}}><span className="stamp-ring">{id==='visit-demo'?<MapPin size={27}/>:id.startsWith('journey')?<Footprints size={27}/>:<Icon name={id==='wudu'?'water':id==='congregational-prayer'?'people':id==='khutbah'?'book':'audio'} size={27}/>}<strong>{id==='visit-demo'?t('زيارة تجريبية','Demo visit'):id.startsWith('journey')?t('رحلة النداء','Call journey'):momentName(id)}</strong><small>{won?new Intl.DateTimeFormat(ar?'ar-SA-u-nu-latn':'en',{day:'numeric',month:'short',calendar:'gregory'}).format(new Date(won.at)):t('بانتظار لحظتك','WAITING FOR YOU')}</small></span><small className="stamp-help">{id==='visit-demo'?t('نموذج تجريبي موسوم','Labeled demo stamp'):won?t('أضفته إلى فهمك','Added to your understanding'):id.startsWith('journey')?t('أكمل الرحلة لنيل الختم','Complete the journey to earn it'):t('افهم اللحظة لنيل الختم','Explore the source-verified explanation')}</small></button>;})}</div><div className="passport-bottom"><span>لَحْظَة</span><span>••• {String(page+1).padStart(2,'0')} •••</span></div></section><div className="passport-pagination"><button className="outlined" disabled={page===0} onClick={()=>setPage(0)}>{t('الصفحة السابقة','Previous page')}</button><button className="outlined" disabled={page===1} onClick={()=>setPage(1)}>{t('الصفحة التالية','Next page')}</button></div><button className="primary" onClick={async()=>{try{const exported=await exportPassport(stamps.map(s=>({...s,label:s.id==='visit-demo'?t('زيارة تجريبية','Demo visit'):s.id.startsWith('journey')?txt(journey):momentName(s.id.replace('moment-',''))})),prefs.lang);setPassportImage(exported);setToast(t('صورة الجواز جاهزة.','Your passport image is ready.'));}catch{setToast(t('تعذّر إنشاء الصورة. أعد المحاولة.','Could not create the image. Please retry.'));}}}><Share2 size={20}/>{t('شارك جوازك صورة','Share your passport image')}</button><p className="fine-print">{t('جوازك لا يتضمن اسمًا أو موقعًا أو محادثات.','Your passport contains no name, location or conversations.')}</p></>}
 {view==='experiences'&&<><div className="demo-notice"><Ticket size={19}/><p>{demoNotice}</p></div><button className="primary" onClick={askLocation}><MapPin size={20}/>{t('أقرب معلم مناسب','Find a nearby place')}</button><div className="panel city-search"><label htmlFor="city-search">{t('أو ابحث بالمدينة','Or search by city')}</label><input id="city-search" value={citySearch} onChange={e=>setCitySearch(e.target.value)} placeholder={t('اكتب اسم المدينة','Enter a city name')}/>{locationStatus&&<p role="status">{locationStatus}</p>}</div>{citySearch&&!cities.some(c=>[c.ar.toLowerCase(),c.en.toLowerCase()].some(v=>v.includes(citySearch.toLowerCase())))?<Empty title={t('لا توجد نماذج لهذه المدينة.','No sample experiences for this city.')} body={t('جرّب الرياض أو جدة أو المدينة المنورة.','Try Riyadh, Jeddah or Madinah.')}/>:<div className="experience-list">{experience.experiences.map(x=><button className="experience-card" key={x.id} onClick={()=>{setExperienceId(x.id);setBookingStep(0);setDate(upcomingDates[0]);go('booking');}}><span className="experience-art"><Icon name={x.icon} size={48}/></span><span className="experience-copy"><span className="badge demo">{t('بيانات نموذجية','SAMPLE DATA')}</span><strong>{txt(x)}</strong><span><Clock3 size={15}/>{x.duration} {t('دقيقة','minutes')}<Globe2 size={15}/>{t('العربية / English','English / العربية')}</span><small>{t('موقع تجريبي · '+(citySearch||city.ar),'Sample location · '+(citySearch||city.en))}</small></span></button>)}</div>}</>}
